import { useEffect, useMemo, useRef, useState } from "react";
import {
  Activity, AlertTriangle, Bell, BrainCircuit, Building2, Check, ChevronDown, CircleGauge,
  CloudSun, Code2, Database, Download, Eye, FileText, Filter, Gauge, HeartPulse, HelpCircle,
  Info, Map, Menu, Network, Play, Printer, Radio, RefreshCw, Satellite, Search, Settings2,
  ShieldCheck, Sparkles, Thermometer, TrendingDown, TrendingUp, TriangleAlert, UserRound, Wrench, X, Zap,
  type LucideIcon,
} from "lucide-react";
import {
  Area, AreaChart, CartesianGrid, Legend, Line, LineChart, ReferenceDot, ResponsiveContainer,
  Tooltip, XAxis, YAxis,
} from "recharts";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Toaster } from "@/components/ui/sonner";
import { cn } from "@/lib/utils";
import { anomalyTypes, baseSeries, initialAlerts, stations, type AlertRecord, type Section, type SensorPoint, type Station, type StationStatus } from "@/lib/skyguard-data";

type SimState = { active:boolean; type:string; score:number; confidence:number; consistency:number; health:number; rootCause:string; step:number; corrected:number };
const initialSim: SimState = { active:false,type:"Normal Operation",score:8,confidence:94,consistency:92,health:91,rootCause:"No fault detected",step:0,corrected:24.8 };

const nav: Array<{id:Section;label:string;icon:LucideIcon}> = [
  {id:"overview",label:"Overview",icon:CircleGauge},{id:"network",label:"Live AWS Network",icon:Map},
  {id:"station",label:"Station Intelligence",icon:Radio},{id:"anomaly",label:"Anomaly Detection",icon:AlertTriangle},
  {id:"xai",label:"Explainable AI",icon:BrainCircuit},{id:"health",label:"Sensor Health",icon:HeartPulse},
  {id:"forecast",label:"Forecast vs Observation",icon:CloudSun},{id:"quality",label:"Data Quality",icon:ShieldCheck},
  {id:"alerts",label:"Alerts",icon:Bell},{id:"maintenance",label:"Maintenance",icon:Wrench},
  {id:"simulation",label:"Simulation Lab",icon:Sparkles},{id:"architecture",label:"Architecture / About",icon:Network},
];

const statusColor: Record<StationStatus,string> = {healthy:"bg-success",warning:"bg-warning",critical:"bg-critical",offline:"bg-offline"};
const css = { cyan:"var(--cyan)", teal:"var(--teal)", warning:"var(--warning)", critical:"var(--critical)", muted:"var(--muted-foreground)", border:"var(--border)", panel:"var(--panel-strong)" };
const primaryStation: Station = { id:"AWS-PN-042",city:"Pune",state:"Maharashtra",x:31,y:66,status:"critical",temperature:24.8,pressure:1008.4,humidity:68.2,health:82,quality:94.2 };
const fallbackPoint: SensorPoint = { time:"10:43",temperature:24.8,pressure:1008.4,humidity:68.2,expectedTemperature:24.7,expectedPressure:1008.5,expectedHumidity:67.9,anomaly:8,health:94 };

export function SkyguardApp() {
  const [entered,setEntered]=useState(false);
  const [section,setSection]=useState<Section>("overview");
  const [mobileNav,setMobileNav]=useState(false);
  const [selected,setSelected]=useState<Station>(stations[0] ?? primaryStation);
  const [filter,setFilter]=useState<StationStatus|"all">("all");
  const [series,setSeries]=useState<SensorPoint[]>(baseSeries);
  const [sim,setSim]=useState<SimState>(initialSim);
  const [alerts,setAlerts]=useState<AlertRecord[]>(initialAlerts);
  const [reportOpen,setReportOpen]=useState(false);
  const [now,setNow]=useState(new Date());
  const demoTimers=useRef<Array<ReturnType<typeof setTimeout>>>([]);

  useEffect(()=>{const t=setInterval(()=>setNow(new Date()),1000);return()=>clearInterval(t)},[]);
  useEffect(()=>()=>demoTimers.current.forEach(clearTimeout),[]);
  useEffect(()=>{
    if(sim.active) return;
    const t=setInterval(()=>setSeries(prev=>{
      const i=prev.length; const next={...(prev.at(-1) ?? fallbackPoint),time:new Date().toLocaleTimeString("en-IN",{hour12:false,hour:"2-digit",minute:"2-digit",second:"2-digit"}),temperature:Number((24.8+Math.sin(i/2)*.35).toFixed(1)),pressure:Number((1008.4+Math.cos(i/3)*.25).toFixed(1)),humidity:Number((68.2+Math.sin(i/3)*.7).toFixed(1)),anomaly:Math.round(6+Math.abs(Math.sin(i))*5)};return [...prev.slice(-19),next];}),3500);return()=>clearInterval(t)
  },[sim.active]);

  const latest: SensorPoint=series.at(-1) ?? baseSeries[0] ?? fallbackPoint;
  const healthy=stations.filter(s=>s.status==="healthy").length;
  const filteredStations=filter==="all"?stations:stations.filter(s=>s.status===filter);
  const go=(id:Section)=>{setSection(id);setEntered(true);setMobileNav(false);window.scrollTo({top:0,behavior:"smooth"})};

  const clearTimers=()=>{demoTimers.current.forEach(clearTimeout);demoTimers.current=[]};
  const reset=()=>{clearTimers();setSeries(baseSeries);setSim(initialSim);setAlerts(initialAlerts);toast.success("Simulation reset — telemetry restored")};
  const applyAnomaly=(type:string, fullDemo=false)=>{
    clearTimers(); setEntered(true); setSection("simulation");
    const scenarios: Record<string,Partial<SensorPoint>>={
      "Temperature Spike":{temperature:55,humidity:91,pressure:1034,correctedTemperature:29.8},
      "Frozen Sensor":{humidity:68.2,correctedHumidity:68.5},"Sensor Drift":{humidity:84.6,correctedHumidity:70.2},
      "Missing Data":{temperature:0,pressure:0,humidity:0},"Communication Error":{temperature:55,pressure:1034,humidity:94},
      "Multivariate Anomaly":{temperature:41.3,pressure:1031,humidity:93,correctedTemperature:29.4},
    };
    const base={...(series.at(-1) ?? fallbackPoint),time:"10:43:20",anomaly:97,health:42,correctedTemperature:29.8,correctedPressure:1008.2,correctedHumidity:72,...(scenarios[type]||scenarios["Temperature Spike"])};
    setSim({...initialSim,active:true,type,score:34,confidence:71,consistency:64,health:77,rootCause:"Analyzing telemetry…",step:1});
    if(fullDemo){
      const sequence=[[29,68,1008],[31,72,1007],[34,82,1016],[55,91,1034]];
      sequence.forEach((vals,i)=>demoTimers.current.push(setTimeout(()=>{
        const p={...base,time:`10:43:${String(i*5+5).padStart(2,"0")}`,temperature:vals[0] as number,humidity:vals[1] as number,pressure:vals[2] as number,anomaly:i===3?97:16+i*21,health:i===3?42:89-i*11};
        setSeries(prev=>[...prev.slice(-19),p]); setSim(s=>({...s,step:i+1,score:p.anomaly,confidence:i===3?98:72+i*7,consistency:i===3?19:83-i*18,health:p.health}));
      },i*850)));
      demoTimers.current.push(setTimeout(()=>finalize(type,base),3800));
    } else { setSeries(prev=>[...prev.slice(-19),base]); demoTimers.current.push(setTimeout(()=>finalize(type,base),800)); }
  };
  const finalize=(type:string,point:SensorPoint)=>{
    setSim({active:true,type,score:97,confidence:98,consistency:19,health:42,rootCause:type==="Communication Error"?"Telemetry Communication Fault":type==="Missing Data"?"Observation Stream Interruption":"Probable Sensor Fault",step:5,corrected:point.correctedTemperature ?? 29.8});
    setAlerts(prev=>[{id:Date.now(),time:"10:43",station:selected.id,parameter:type.includes("Humidity")?"Humidity":"Temperature",type,severity:"CRITICAL",confidence:98,status:"Open",priority:"P1"},...prev]);
    toast.error("Critical anomaly detected",{description:`${type} at ${selected.id} • 98% confidence`});
  };
  const updateAlert=(id:number,status:string)=>{setAlerts(a=>a.map(v=>v.id===id?{...v,status}:v));toast.success(`Alert marked ${status.toLowerCase()}`)};

  if(!entered) return <Landing onEnter={()=>setEntered(true)} onDemo={()=>{setEntered(true);setTimeout(()=>applyAnomaly("Temperature Spike",true),50)}}/>;
  return <div className="min-h-screen atmospheric-grid">
    <Sidebar section={section} go={go} open={mobileNav} close={()=>setMobileNav(false)}/>
    <div className="lg:pl-64">
      <Topbar now={now} openNav={()=>setMobileNav(true)} alerts={alerts.length} />
      <main className="mx-auto max-w-[1600px] p-4 sm:p-6 lg:p-7">
        <PageHeading section={section} sim={sim} />
        {section==="overview"&&<Overview latest={latest} sim={sim} healthy={healthy} go={go} runDemo={()=>applyAnomaly("Temperature Spike",true)} />}
        {section==="network"&&<NetworkView stations={filteredStations} selected={selected} setSelected={s=>{setSelected(s);go("station")}} filter={filter} setFilter={setFilter}/>} 
        {section==="station"&&<StationView station={selected} series={series} sim={sim}/>} 
        {section==="anomaly"&&<AnomalyView series={series} sim={sim}/>} 
        {section==="xai"&&<XaiView sim={sim}/>} 
        {section==="health"&&<HealthView sim={sim}/>} 
        {section==="forecast"&&<ForecastView series={series} sim={sim}/>} 
        {section==="quality"&&<QualityView sim={sim}/>} 
        {section==="alerts"&&<AlertsView alerts={alerts} update={updateAlert} explain={()=>go("xai")}/>} 
        {section==="maintenance"&&<MaintenanceView sim={sim}/>} 
        {section==="simulation"&&<SimulationView latest={latest} series={series} sim={sim} inject={applyAnomaly} reset={reset} report={()=>setReportOpen(true)}/>} 
        {section==="architecture"&&<ArchitectureView/>}
      </main>
    </div>
    {reportOpen&&<IncidentReport sim={sim} station={selected} latest={latest} close={()=>setReportOpen(false)}/>}<Toaster richColors position="top-right"/>
  </div>
}

function Landing({onEnter,onDemo}:{onEnter:()=>void;onDemo:()=>void}){
 const features: Array<[LucideIcon,string]>=[[Radio,"Real-Time Monitoring"],[BrainCircuit,"Explainable AI"],[RefreshCw,"Self-Healing Data"],[Wrench,"Predictive Maintenance"]];
 return <main className="relative min-h-screen overflow-hidden atmospheric-grid px-5 py-8 sm:px-10">
  <div className="absolute inset-x-0 top-0 h-px scanline"/><div className="pointer-events-none absolute left-[70%] top-[17%] size-72 rounded-full border border-primary/10 animate-float"><div className="absolute inset-10 rounded-full border border-primary/10"/><div className="absolute inset-24 rounded-full border border-primary/20"/></div>
  <header className="relative mx-auto flex max-w-7xl items-center justify-between"><Brand/><span className="hidden text-xs font-semibold uppercase text-muted-foreground sm:block">SIH 26073 • IMD / MoES Prototype</span></header>
  <section className="relative mx-auto grid min-h-[76vh] max-w-7xl content-center gap-12 lg:grid-cols-[1.1fr_.9fr] lg:items-center">
   <div className="max-w-3xl"><div className="mb-5 flex items-center gap-2 text-xs font-bold uppercase tracking-[.2em] text-primary"><span className="size-2 rounded-full bg-success shadow-[0_0_16px_var(--success)]"/>National AWS Intelligence Platform</div>
    <h1 className="font-display text-6xl font-semibold leading-[.88] tracking-normal text-foreground sm:text-8xl lg:text-9xl">SKYGUARD<br/><span className="text-primary">AI</span></h1>
    <p className="mt-7 font-display text-2xl font-medium text-foreground sm:text-3xl">Trust Every Weather Observation.</p>
    <p className="mt-4 max-w-2xl text-sm leading-7 text-muted-foreground sm:text-base">AI-powered anomaly detection, explainable sensor intelligence and predictive maintenance for resilient Automatic Weather Stations.</p>
    <div className="mt-8 flex flex-wrap gap-3"><Button size="xl" onClick={onEnter}>Enter Command Center <Activity/></Button><Button size="xl" variant="command" onClick={onDemo}><Play/> Run Live AI Demo</Button></div>
    <p className="mt-6 text-xs font-semibold uppercase tracking-[.24em] text-muted-foreground">Detect <span className="text-primary">•</span> Explain <span className="text-primary">•</span> Correct <span className="text-primary">•</span> Predict</p>
   </div>
   <div className="relative mx-auto aspect-square w-full max-w-md"><RadarVisual/></div>
  </section>
  <section className="relative mx-auto grid max-w-7xl grid-cols-2 border-t border-border lg:grid-cols-4">{features.map(([Icon,label])=><div key={label} className="flex items-center gap-3 border-b border-border p-5 lg:border-b-0 lg:border-r"><Icon className="text-primary"/><span className="text-xs font-semibold uppercase text-foreground">{label}</span></div>)}</section>
 </main>
}
function Brand(){return <div className="flex items-center gap-3"><div className="grid size-10 place-items-center border border-primary/40 bg-primary/10"><Satellite className="text-primary"/></div><div><div className="font-display text-xl font-bold leading-none">SKYGUARD <span className="text-primary">AI</span></div><div className="mt-1 text-[9px] font-bold uppercase tracking-[.19em] text-muted-foreground">Weather Intelligence</div></div></div>}
function RadarVisual(){return <div className="relative size-full rounded-full border border-primary/25 bg-primary/[.03] shadow-[0_0_80px_color-mix(in_oklab,var(--cyan)_10%,transparent)]"><div className="absolute inset-[12%] rounded-full border border-primary/20"/><div className="absolute inset-[28%] rounded-full border border-primary/20"/><div className="absolute left-1/2 top-0 h-full w-px bg-primary/15"/><div className="absolute left-0 top-1/2 h-px w-full bg-primary/15"/><div className="absolute inset-1/2 origin-left animate-[spin_6s_linear_infinite] border-t border-primary shadow-[0_-8px_24px_var(--primary)]"/><div className="absolute left-[65%] top-[28%] size-3 rounded-full bg-warning animate-critical"/><div className="absolute left-[24%] top-[62%] size-2 rounded-full bg-success shadow-[0_0_14px_var(--success)]"/><div className="absolute inset-0 grid place-items-center"><div className="text-center"><div className="text-data text-5xl font-semibold">128</div><div className="text-[10px] font-bold uppercase tracking-[.2em] text-muted-foreground">Stations online</div></div></div></div>}

function Sidebar({section,go,open,close}:{section:Section;go:(s:Section)=>void;open:boolean;close:()=>void}){return <><aside className={cn("fixed inset-y-0 left-0 z-40 flex w-64 flex-col border-r border-border bg-background/95 p-4 backdrop-blur-xl transition-transform lg:translate-x-0",open?"translate-x-0":"-translate-x-full")}><div className="flex items-center justify-between px-2 py-2"><Brand/><Button variant="ghost" size="icon" className="lg:hidden" onClick={close} aria-label="Close navigation"><X/></Button></div><div className="mt-7 flex-1 space-y-1 overflow-y-auto">{nav.map(item=><Button key={item.id} variant="ghost" onClick={()=>go(item.id)} className={cn("h-10 w-full justify-start px-3 text-xs",section===item.id?"border border-primary/25 bg-primary/10 text-primary":"text-muted-foreground hover:text-foreground")}><item.icon/>{item.label}</Button>)}</div><div className="mt-4 border-t border-border pt-4"><div className="flex items-center gap-3 px-2"><div className="grid size-9 place-items-center rounded-full bg-secondary"><Building2 className="size-4 text-primary"/></div><div><p className="text-xs font-semibold">IMD Operations</p><p className="text-[10px] text-muted-foreground">National network</p></div></div></div></aside>{open&&<button className="fixed inset-0 z-30 bg-background/80 lg:hidden" onClick={close} aria-label="Close navigation overlay"/>}</>}
function Topbar({now,openNav,alerts}:{now:Date;openNav:()=>void;alerts:number}){return <header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-border bg-background/75 px-4 backdrop-blur-xl sm:px-6"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="lg:hidden" onClick={openNav} aria-label="Open navigation"><Menu/></Button><div className="hidden items-center gap-2 text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground sm:flex"><span className="size-2 rounded-full bg-success shadow-[0_0_10px_var(--success)]"/>System operational</div></div><div className="flex items-center gap-2 sm:gap-4"><div className="hidden text-right sm:block"><p className="text-data text-xs font-semibold">{now.toLocaleTimeString("en-IN",{hour12:false})} IST</p><p className="text-[9px] uppercase text-muted-foreground">{now.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"})}</p></div><Button variant="ghost" size="icon" className="relative" aria-label="Notifications"><Bell/><span className="absolute right-1 top-1 grid size-4 place-items-center rounded-full bg-critical text-[8px] text-foreground">{alerts}</span></Button><div className="grid size-9 place-items-center rounded-full border border-primary/30 bg-primary/10"><UserRound className="size-4 text-primary"/></div></div></header>}
function PageHeading({section,sim}:{section:Section;sim:SimState}){const item=nav.find(n=>n.id===section);return <div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.2em] text-primary">Operations / {item?.label}</div><h1 className="mt-1 font-display text-3xl font-semibold tracking-normal sm:text-4xl">{item?.label}</h1></div><div className="flex items-center gap-2"><span className="rounded-sm border border-border bg-panel px-2 py-1 text-[9px] font-bold uppercase text-muted-foreground">Simulated inference</span>{sim.active&&<span className="animate-critical rounded-sm border border-critical/50 bg-critical/15 px-2 py-1 text-[9px] font-bold uppercase text-critical">Active incident</span>}</div></div>}
function Panel({title,eyebrow,children,className,action}:{title?:string;eyebrow?:string;children:React.ReactNode;className?:string;action?:React.ReactNode}){return <section className={cn("glass-panel overflow-hidden rounded-lg",className)}>{(title||eyebrow||action)&&<header className="flex items-center justify-between border-b border-border px-4 py-3"><div>{eyebrow&&<p className="text-[9px] font-bold uppercase tracking-[.18em] text-primary">{eyebrow}</p>}{title&&<h2 className="mt-0.5 font-display text-lg font-semibold">{title}</h2>}</div>{action}</header>}<div className="p-4">{children}</div></section>}
function Metric({label,value,sub,icon:Icon,tone="primary"}:{label:string;value:string;sub:string;icon:LucideIcon;tone?:"primary"|"warning"|"critical"|"success"}){return <div className="glass-panel rounded-lg p-4 transition-transform hover:-translate-y-0.5"><div className="flex items-start justify-between"><p className="text-[10px] font-bold uppercase tracking-[.13em] text-muted-foreground">{label}</p><Icon className={cn("size-4",tone==="critical"?"text-critical":tone==="warning"?"text-warning":tone==="success"?"text-success":"text-primary")}/></div><p className="text-data mt-3 text-3xl font-semibold">{value}</p><p className="mt-1 text-[10px] text-muted-foreground">{sub}</p></div>}
function GaugeRing({value,label,tone="primary",size="lg"}:{value:number;label:string;tone?:"primary"|"critical"|"warning";size?:"sm"|"lg"}){const c=tone==="critical"?css.critical:tone==="warning"?css.warning:css.cyan;return <div className={cn("relative grid shrink-0 place-items-center rounded-full",size==="lg"?"size-36":"size-24")} style={{background:`conic-gradient(${c} ${value*3.6}deg, color-mix(in oklab,var(--muted) 65%,transparent) 0)`}}><div className="absolute inset-[7px] grid place-items-center rounded-full bg-background"><div className="text-center"><div className={cn("text-data font-semibold",size==="lg"?"text-4xl":"text-2xl")}>{value}<span className="text-sm">%</span></div><div className="mt-1 text-[8px] font-bold uppercase tracking-wider text-muted-foreground">{label}</div></div></div></div>}
function Overview({latest,sim,healthy,go,runDemo}:{latest:SensorPoint;sim:SimState;healthy:number;go:(s:Section)=>void;runDemo:()=>void}){return <div className="space-y-5">
 <section className="relative overflow-hidden rounded-lg border border-primary/25 bg-primary/[.04] p-5 sm:p-7"><div className="absolute inset-x-0 top-0 h-px scanline"/><div className="relative flex flex-col justify-between gap-6 lg:flex-row lg:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-primary">Live system status • Operational</p><h2 className="mt-3 max-w-3xl font-display text-4xl font-semibold leading-none sm:text-5xl">Trustworthy weather data.<br/><span className="text-primary">Before it becomes a risk.</span></h2><p className="mt-4 max-w-2xl text-sm leading-6 text-muted-foreground">Real-time AI-powered anomaly detection and sensor health intelligence for Automatic Weather Stations.</p></div><div className="flex gap-2"><Button variant="command" onClick={()=>go("network")}><Map/>View network</Button><Button onClick={runDemo}><Play/>Run AI demo</Button></div></div></section>
 <div className="grid grid-cols-2 gap-3 lg:grid-cols-3 xl:grid-cols-6"><Metric label="AWS monitored" value="128" sub="123 online" icon={Satellite}/><Metric label="Healthy stations" value="113" sub={`${healthy} visible in demo`} icon={ShieldCheck} tone="success"/><Metric label="Active anomalies" value={sim.active?"06":"05"} sub="10 warnings" icon={AlertTriangle} tone="warning"/><Metric label="Critical alerts" value={sim.active?"06":"05"} sub={sim.active?"1 new incident":"Stable for 12 min"} icon={TriangleAlert} tone="critical"/><Metric label="Data quality" value={sim.active?"91.4%":"96.8%"} sub="Across network" icon={Database}/><Metric label="Network health" value={sim.active?"91.7%":"94.2%"} sub="Resilience 94%" icon={Activity}/></div>
 <div className="grid gap-5 xl:grid-cols-[1.45fr_.8fr]"><Panel title="National AWS Network" eyebrow="Live topology" action={<Button variant="ghost" size="sm" onClick={()=>go("network")}>Expand <Map/></Button>}><MiniIndiaMap/></Panel><Panel title="AI Decision State" eyebrow="Inference engine"><div className="flex items-center gap-5"><GaugeRing value={sim.score} label="Anomaly" tone={sim.score>80?"critical":"primary"}/><div className="min-w-0 flex-1 space-y-3"><StatusRow label="Confidence" value={`${sim.confidence}%`}/><StatusRow label="Atmospheric consistency" value={`${sim.consistency}%`} warning={sim.consistency<50}/><StatusRow label="Station health" value={`${sim.health}%`} warning={sim.health<60}/><div className={cn("rounded-md border p-3",sim.active?"border-critical/40 bg-critical/10":"border-primary/20 bg-primary/5")}><p className="text-[9px] font-bold uppercase text-muted-foreground">Classification</p><p className={cn("mt-1 text-sm font-semibold",sim.active?"text-critical":"text-success")}>{sim.rootCause}</p></div></div></div></Panel></div>
 <div className="grid gap-5 xl:grid-cols-[1.4fr_1fr]"><SensorMonitoring latest={latest} sim={sim}/><ReasoningCard sim={sim}/></div>
 </div>}
function StatusRow({label,value,warning=false}:{label:string;value:string;warning?:boolean}){return <div className="flex items-center justify-between border-b border-border pb-2"><span className="text-xs text-muted-foreground">{label}</span><span className={cn("text-data text-sm font-semibold",warning?"text-critical":"text-foreground")}>{value}</span></div>}
function MiniIndiaMap(){return <div className="relative min-h-[310px] overflow-hidden rounded-md bg-background/35"><IndiaShape/>{stations.map(s=><div key={s.id} className={cn("absolute size-2.5 rounded-full border-2 border-background",statusColor[s.status],s.status==="critical"&&"animate-critical")} style={{left:`${s.x}%`,top:`${s.y}%`}} title={`${s.city} • ${s.status}`}/>)}<div className="absolute bottom-3 left-3 flex flex-wrap gap-3 rounded-sm border border-border bg-background/80 px-3 py-2 text-[9px] uppercase">{(["healthy","warning","critical","offline"] as const).map(s=><span key={s} className="flex items-center gap-1.5"><i className={cn("size-1.5 rounded-full",statusColor[s])}/>{s}</span>)}</div></div>}
function IndiaShape(){return <svg viewBox="0 0 450 420" className="absolute inset-0 h-full w-full opacity-60" aria-label="Stylized map of India"><path d="M144 33l53 16 40-13 22 30 54 3 18 34 50 23-45 21-19 35-41 10 16 54-28 48-11 68-30 44-16-83-41-37-5-52-35-44 20-37-44-18 24-43-18-29 56-50Z" fill="color-mix(in oklab,var(--primary) 8%,transparent)" stroke="var(--primary)" strokeWidth="1.5"/><path d="M77 145C190 85 260 292 374 140M121 303C212 246 282 164 344 110" fill="none" stroke="color-mix(in oklab,var(--cyan) 22%,transparent)" strokeDasharray="3 7"/></svg>}
function SensorMonitoring({latest,sim}:{latest:SensorPoint;sim:SimState}){const rows=[{n:"Temperature",v:latest.temperature,u:"°C",d:"↓ 0.7%",range:"18–34°C",icon:Thermometer},{n:"Pressure",v:latest.pressure,u:"hPa",d:"↑ 0.2%",range:"995–1020 hPa",icon:Gauge},{n:"Humidity",v:latest.humidity,u:"%",d:"↑ 2.4%",range:"35–85%",icon:CloudSun}];return <Panel title="Live Sensor Monitoring" eyebrow="AWS-PN-042 • Pune" action={<span className="flex items-center gap-1 text-[9px] font-bold uppercase text-success"><i className="size-1.5 rounded-full bg-success animate-pulse"/>Live streaming</span>}><div className="grid gap-3 md:grid-cols-3">{rows.map((r,i)=><div key={r.n} className={cn("rounded-md border p-4",sim.active&&((i===0&&latest.temperature>40)||(i===1&&latest.pressure>1025)||(i===2&&latest.humidity>90))?"border-critical/45 bg-critical/10":"border-border bg-background/30")}><div className="flex items-center justify-between"><span className="text-[9px] font-bold uppercase text-muted-foreground">{r.n}</span><r.icon className="size-4 text-primary"/></div><p className="text-data mt-2 text-3xl font-semibold">{r.v}<span className="ml-1 text-xs text-muted-foreground">{r.u}</span></p><div className="mt-3 flex justify-between text-[9px]"><span className="text-primary">{r.d}</span><span className={sim.active&&i===0?"text-critical":"text-success"}>{sim.active&&i===0?"ANOMALY":"NORMAL"}</span></div><p className="mt-2 text-[9px] text-muted-foreground">Normal range {r.range}</p></div>)}</div></Panel>}
function ReasoningCard({sim}:{sim:SimState}){const reasons=sim.active?["Temperature increased 24.8°C within 2 minutes","Pattern differs significantly from station history","Temperature conflicts with humidity behavior","Pressure trend rejects a genuine weather event","Neighboring stations remain stable"]:["Observations remain inside learned baseline","Cross-sensor relationships are coherent","Neighboring station behavior is consistent","No meaningful temporal deviation detected"];return <Panel title="Why did SkyGuard flag this?" eyebrow="AI reasoning"><div className="space-y-3">{reasons.map((r,i)=><div key={r} className="flex gap-3"><span className={cn("mt-0.5 grid size-4 shrink-0 place-items-center rounded-full",sim.active?"bg-warning/15 text-warning":"bg-success/15 text-success")}><Check className="size-3"/></span><div className="flex-1"><p className="text-xs leading-5">{r}</p><div className="mt-1 h-1 overflow-hidden rounded-full bg-muted"><div className={cn("h-full",sim.active?"bg-warning":"bg-success")} style={{width:`${sim.active?96-i*7:89-i*5}%`}}/></div></div></div>)}</div><div className="mt-4 rounded-md border border-primary/20 bg-primary/5 p-3"><p className="text-[9px] font-bold uppercase text-primary">Final assessment</p><p className="mt-1 text-xs leading-5">{sim.active?'High probability of sensor malfunction rather than a genuine meteorological event.':'Station behavior is meteorologically coherent. No intervention required.'}</p><p className="text-data mt-2 text-lg font-semibold">{sim.confidence}% <span className="text-xs text-muted-foreground">confidence</span></p></div></Panel>}
function NetworkView({stations,selected,setSelected,filter,setFilter}:{stations:Station[];selected:Station;setSelected:(s:Station)=>void;filter:StationStatus|"all";setFilter:(s:StationStatus|"all")=>void}){return <div className="grid gap-5 xl:grid-cols-[1.55fr_.65fr]"><Panel title="India AWS Network" eyebrow="14 representative stations" className="min-h-[650px]" action={<span className="text-data text-xs text-muted-foreground">Resilience <b className="text-primary">94%</b></span>}><div className="mb-4 flex flex-wrap gap-2">{(["all","healthy","warning","critical","offline"] as const).map(f=><Button key={f} size="sm" variant={filter===f?"default":"command"} onClick={()=>setFilter(f)} className="capitalize">{f}</Button>)}</div><div className="relative h-[520px] overflow-hidden rounded-md bg-background/45"><IndiaShape/>{stations.map(s=><button key={s.id} onClick={()=>setSelected(s)} aria-label={`Open ${s.city} station`} className={cn("group absolute grid size-6 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border border-background transition-transform hover:scale-125",statusColor[s.status],s.status==="critical"&&"animate-critical")} style={{left:`${s.x}%`,top:`${s.y}%`}}><span className="absolute left-7 hidden w-max rounded-sm border border-border bg-popover px-2 py-1 text-left text-[9px] text-popover-foreground shadow-lg group-hover:block"><b>{s.city}</b><br/>{s.id} • {s.health}% health</span></button>)}</div></Panel><div className="space-y-5"><Panel title="Network Resilience" eyebrow="National health"><div className="flex justify-center"><GaugeRing value={94} label="Resilience"/></div><div className="mt-5 space-y-2"><StatusRow label="Total stations" value="128"/><StatusRow label="Online" value="123"/><StatusRow label="With anomalies" value="15" warning/><StatusRow label="Maintenance due" value="08" warning/></div></Panel><Panel title="Selected Station" eyebrow={selected.id}><p className="font-display text-2xl font-semibold">{selected.city}</p><p className="text-xs text-muted-foreground">{selected.state}</p><div className="mt-4 grid grid-cols-3 gap-2 text-center"><SmallStat v={`${selected.temperature}°`} l="Temp"/><SmallStat v={`${selected.pressure}`} l="hPa"/><SmallStat v={`${selected.humidity}%`} l="RH"/></div></Panel></div></div>}
function SmallStat({v,l}:{v:string;l:string}){return <div className="rounded-md border border-border bg-background/30 p-2"><p className="text-data text-lg font-semibold">{v}</p><p className="text-[8px] uppercase text-muted-foreground">{l}</p></div>}
function StationView({station,series,sim}:{station:Station;series:SensorPoint[];sim:SimState}){return <div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Station ID" value={station.id} sub={`${station.city}, ${station.state}`} icon={Radio}/><Metric label="Overall health" value={`${sim.active?sim.health:station.health}%`} sub="Temperature • Pressure • RH" icon={HeartPulse} tone={sim.active?"critical":"success"}/><Metric label="Data quality" value={`${sim.active?88.9:station.quality}%`} sub="Last 24 hours" icon={ShieldCheck}/><Metric label="Anomaly count" value={sim.active?"06":"02"} sub="Last 24 hours" icon={AlertTriangle} tone="warning"/><Metric label="Maintenance risk" value={sim.active?"HIGH":"LOW"} sub="Last calibration 18d ago" icon={Wrench} tone={sim.active?"critical":"success"}/></div><Panel title="24-Hour Telemetry" eyebrow={`${station.id} • Last update just now`}><TelemetryChart data={series} anomaly={sim.active}/></Panel><div className="grid gap-5 xl:grid-cols-2"><SensorMonitoring latest={series.at(-1)??baseSeries[0]??fallbackPoint} sim={sim}/><Panel title="AI Station Assessment" eyebrow="Operational summary"><div className={cn("rounded-md border p-4",sim.active?"border-critical/40 bg-critical/10":"border-success/30 bg-success/5")}><div className="flex items-center gap-3">{sim.active?<TriangleAlert className="text-critical"/>:<ShieldCheck className="text-success"/>}<p className="font-display text-xl font-semibold">{sim.active?"Immediate review required":"Station operating normally"}</p></div><p className="mt-3 text-sm leading-6 text-muted-foreground">{sim.active?"A probable sensor fault is affecting temperature observations. AI correction is available while calibration is verified.":"No significant anomalies detected during the last 24 hours. All monitored sensors are within expected operational envelopes."}</p></div></Panel></div></div>}
function TelemetryChart({data,anomaly=false}:{data:SensorPoint[];anomaly?:boolean}){const point=data.at(-1)??fallbackPoint;return <div className="h-[330px] w-full"><ResponsiveContainer><LineChart data={data} margin={{top:15,right:12,bottom:0,left:-22}}><CartesianGrid stroke={css.border} strokeDasharray="3 6"/><XAxis dataKey="time" stroke={css.muted} tick={{fontSize:9}}/><YAxis yAxisId="temp" stroke={css.muted} tick={{fontSize:9}} domain={[0,60]}/><YAxis yAxisId="pressure" orientation="right" stroke={css.muted} tick={{fontSize:9}} domain={[990,1040]}/><Tooltip contentStyle={{background:css.panel,border:`1px solid ${css.border}`,fontSize:11}}/><Legend wrapperStyle={{fontSize:10}}/><Line yAxisId="temp" dataKey="temperature" name="Temperature °C" stroke={css.cyan} strokeWidth={2} dot={false}/><Line yAxisId="pressure" dataKey="pressure" name="Pressure hPa" stroke={css.teal} strokeWidth={1.5} dot={false}/><Line yAxisId="temp" dataKey="humidity" name="Humidity %" stroke={css.warning} strokeWidth={1.5} dot={false}/>{anomaly&&<ReferenceDot yAxisId="temp" x={point.time} y={point.temperature} r={6} fill={css.critical} stroke={css.critical}/>}</LineChart></ResponsiveContainer></div>}
function AnomalyView({series,sim}:{series:SensorPoint[];sim:SimState}){return <div className="space-y-5"><div className="grid gap-5 xl:grid-cols-[1.4fr_.75fr]"><Panel title="AI Anomaly Engine" eyebrow="Ensemble inference"><TelemetryChart data={series} anomaly={sim.active}/></Panel><Panel title="Current Classification" eyebrow="Decision output"><div className="flex justify-center"><GaugeRing value={sim.score} label="Anomaly score" tone={sim.score>80?"critical":"primary"}/></div><div className="mt-5 space-y-2"><StatusRow label="Confidence" value={`${sim.confidence}%`}/><StatusRow label="Severity" value={sim.active?"CRITICAL":"LOW"} warning={sim.active}/><StatusRow label="Root cause" value={sim.rootCause} warning={sim.active}/></div></Panel></div><Panel title="Anomaly Taxonomy" eyebrow="Detection coverage"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{anomalyTypes.map(([name,desc,logic,count,severity])=><div key={name} className="rounded-md border border-border bg-background/30 p-4"><div className="flex items-center justify-between"><AlertTriangle className="size-4 text-warning"/><span className="text-data text-xl font-semibold">{count}</span></div><h3 className="mt-3 text-sm font-semibold">{name}</h3><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{desc}</p><div className="mt-3 flex justify-between text-[8px] uppercase"><span className="text-primary">{logic}</span><span className={severity==="CRITICAL"?"text-critical":"text-warning"}>{severity}</span></div></div>)}</div></Panel><AnomalyTimeline active={sim.active}/></div>}
function AnomalyTimeline({active}:{active:boolean}){const events=active?[["10:42:10","Normal observations"],["10:42:30","Temperature begins abnormal rise"],["10:42:50","Multivariate inconsistency detected"],["10:43:05","AI score crosses threshold"],["10:43:10","Critical alert generated"],["10:43:15","Root cause classification completed"],["10:43:20","Corrected value generated"]]:[["10:38:10","Observation received"],["10:38:11","Temporal validation passed"],["10:38:12","Multivariate validation passed"],["10:38:13","Observation trusted"]];return <Panel title="Anomaly Timeline" eyebrow="Decision trace"><div className="grid gap-3 md:grid-cols-4 xl:grid-cols-7">{events.map(([t,e],i)=><div key={t} className="relative border-l border-border pl-3"><span className={cn("absolute -left-1 top-0 size-2 rounded-full",active&&i>2?"bg-critical":"bg-primary")}/><p className="text-data text-xs text-primary">{t}</p><p className="mt-2 text-[10px] leading-4 text-muted-foreground">{e}</p></div>)}</div></Panel>}
function XaiView({sim}:{sim:SimState}){const contributions=[["Temperature deviation",sim.active?82:12],["Humidity inconsistency",sim.active?61:8],["Pressure deviation",sim.active?48:6],["Temporal deviation",sim.active?74:11]];return <div className="grid gap-5 xl:grid-cols-2"><ReasoningCard sim={sim}/><Panel title="Explainable AI — Feature Contribution" eyebrow="SHAP-style analysis"><div className="space-y-5">{contributions.map(([l,v])=><div key={l as string}><div className="mb-2 flex justify-between text-xs"><span>{l}</span><span className="text-data text-primary">{v}%</span></div><div className="h-3 overflow-hidden rounded-sm bg-muted"><div className={cn("h-full transition-all duration-700",sim.active?"bg-primary":"bg-success")} style={{width:`${v}%`}}/></div></div>)}</div><p className="mt-6 rounded-md border border-border bg-background/30 p-3 text-xs text-muted-foreground">{sim.active?"Temperature deviation contributed most strongly to the anomaly classification.":"No individual feature is contributing materially to an anomaly decision."}</p></Panel><Consistency sim={sim}/><DigitalTwin sim={sim}/></div>}
function Consistency({sim}:{sim:SimState}){const vals=sim.active?[19,23,31,18]:[92,88,95,91];return <Panel title="Atmospheric Consistency Score" eyebrow="Multivariate intelligence"><div className="flex items-center gap-6"><GaugeRing value={vals[0]} label="Consistency" tone={vals[0]<50?"critical":"primary"} size="sm"/><div className="flex-1 space-y-2"><StatusRow label="Temperature ↔ Humidity" value={`${vals[1]}%`} warning={vals[1]<50}/><StatusRow label="Temperature ↔ Pressure" value={`${vals[2]}%`} warning={vals[2]<50}/><StatusRow label="Humidity ↔ Pressure" value={`${vals[3]}%`} warning={vals[3]<50}/></div></div><p className="mt-4 text-xs text-muted-foreground">{sim.active?"Observed values are inconsistent with learned temporal and multivariate patterns.":"Observed relationships align with learned atmospheric behavior."}</p></Panel>}
function DigitalTwin({sim}:{sim:SimState}){const data=[{l:"Temperature",u:"°C",e:28.7,o:sim.active?55:28.8,c:sim.active?29.8:28.8},{l:"Pressure",u:"hPa",e:1009.2,o:sim.active?1034.1:1009.4,c:sim.active?1009:1009.4},{l:"Humidity",u:"%",e:72,o:sim.active?94:71,c:sim.active?73:71}];return <Panel title="Sensor Digital Twin" eyebrow="Expected vs observed vs corrected"><div className="space-y-4">{data.map(d=><div key={d.l}><p className="mb-2 text-xs font-semibold">{d.l}</p><div className="grid grid-cols-3 gap-2"><TwinValue label="Expected" v={`${d.e}${d.u}`}/><TwinValue label="Observed" v={`${d.o}${d.u}`} bad={sim.active}/><TwinValue label="AI estimated" v={`${d.c}${d.u}`} ai/></div></div>)}</div></Panel>}
function TwinValue({label,v,bad,ai}:{label:string;v:string;bad?:boolean;ai?:boolean}){return <div className={cn("rounded-md border p-2",bad?"border-critical/40 bg-critical/10":ai?"border-primary/35 bg-primary/10":"border-border bg-background/30")}><p className="text-[8px] font-bold uppercase text-muted-foreground">{label}</p><p className={cn("text-data mt-1 text-sm font-semibold",bad?"text-critical":ai?"text-primary":"")}>{v}</p></div>}
function HealthView({sim}:{sim:SimState}){const sensors=[{n:"Temperature Sensor",v:sim.active?42:91,cal:"18 days ago",freq:sim.active?"↑ 4.8x":"0.8 / day",miss:"0.2%",drift:sim.active?"Severe":"Low"},{n:"Pressure Sensor",v:96,cal:"11 days ago",freq:"0.2 / day",miss:"0.1%",drift:"Minimal"},{n:"Humidity Sensor",v:63,cal:"67 days ago",freq:"2.4 / day",miss:"1.8%",drift:"Moderate"}];return <div className="space-y-5"><div className="grid gap-5 lg:grid-cols-3">{sensors.map(s=><Panel key={s.n} title={s.n} eyebrow={s.v>=90?"Excellent":s.v>=75?"Good":s.v>=50?"Degrading":"Critical"}><div className="flex justify-center"><GaugeRing value={s.v} label="Health" tone={s.v<50?"critical":s.v<75?"warning":"primary"}/></div><div className="mt-5 space-y-2"><StatusRow label="Last calibration" value={s.cal}/><StatusRow label="Anomaly frequency" value={s.freq} warning={s.v<50}/><StatusRow label="Data missing rate" value={s.miss}/><StatusRow label="Drift score" value={s.drift} warning={s.drift==="Severe"}/></div></Panel>)}</div><Panel title="Health Degradation Trend" eyebrow="Predictive signal"><HealthChart active={sim.active}/></Panel></div>}
function HealthChart({active}:{active:boolean}){const data=Array.from({length:12},(_,i)=>({day:`D-${11-i}`,temperature:active?Math.max(42,94-i*3.8):94-i*.25,pressure:97-i*.08,humidity:78-i*1.35}));return <div className="h-72"><ResponsiveContainer><AreaChart data={data}><defs><linearGradient id="healthFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={css.cyan} stopOpacity={.35}/><stop offset="1" stopColor={css.cyan} stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke={css.border} strokeDasharray="3 6"/><XAxis dataKey="day" stroke={css.muted} tick={{fontSize:9}}/><YAxis domain={[0,100]} stroke={css.muted} tick={{fontSize:9}}/><Tooltip contentStyle={{background:css.panel,border:`1px solid ${css.border}`}}/><Area type="monotone" dataKey="temperature" stroke={active?css.critical:css.cyan} fill="url(#healthFill)"/><Line type="monotone" dataKey="pressure" stroke={css.teal}/><Line type="monotone" dataKey="humidity" stroke={css.warning}/></AreaChart></ResponsiveContainer></div>}
function ForecastView({series,sim}:{series:SensorPoint[];sim:SimState}){const latest:SensorPoint=series.at(-1)??baseSeries[0]??fallbackPoint;const deviations=[["Temperature",`${sim.active?"+26.3":"+0.2"}°C`,sim.active],["Pressure",`${sim.active?"+25.2":"+0.2"} hPa`,sim.active],["Humidity",`${sim.active?"+22":"+0.4"}%`,sim.active]];return <div className="space-y-5"><div className="grid gap-3 sm:grid-cols-3">{deviations.map(([l,v,b])=><Metric key={l as string} label={`${l} deviation`} value={v as string} sub={b?"Outside expected envelope":"Within expected envelope"} icon={TrendingUp} tone={b?"critical":"success"}/>)}</div><Panel title="Expected Pattern vs Actual Observation" eyebrow="Digital twin residuals"><div className="h-[430px]"><ResponsiveContainer><LineChart data={series}><CartesianGrid stroke={css.border} strokeDasharray="3 6"/><XAxis dataKey="time" stroke={css.muted} tick={{fontSize:9}}/><YAxis domain={[0,60]} stroke={css.muted} tick={{fontSize:9}}/><Tooltip contentStyle={{background:css.panel,border:`1px solid ${css.border}`}}/><Legend wrapperStyle={{fontSize:10}}/><Line dataKey="expectedTemperature" name="AI Expected" stroke={css.teal} strokeWidth={2} dot={false} strokeDasharray="6 5"/><Line dataKey="temperature" name="Observed" stroke={sim.active?css.critical:css.cyan} strokeWidth={2.5} dot={false}/><Line dataKey="correctedTemperature" name="AI Corrected" stroke={css.warning} strokeWidth={2} connectNulls dot={false}/></LineChart></ResponsiveContainer></div><div className="mt-2 grid grid-cols-3 gap-3"><TwinValue label="Expected" v={`${latest.expectedTemperature}°C`}/><TwinValue label="Observed" v={`${latest.temperature}°C`} bad={sim.active}/><TwinValue label="AI estimated" v={`${latest.correctedTemperature??latest.temperature}°C`} ai/></div></Panel></div>}
function QualityView({sim}:{sim:SimState}){const metrics=[["Completeness",sim.active?94.3:98.2],["Consistency",sim.active?71.4:94.8],["Validity",sim.active?82.6:97.1],["Timeliness",99.4],["Stability",sim.active?76.8:95.1]];const overall=sim.active?84.9:96.8;return <div className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><Panel title="Weather Data Trust Score" eyebrow="Network quality"><div className="flex justify-center"><GaugeRing value={overall} label="Trust score" tone={overall<90?"warning":"primary"}/></div><p className="mt-5 text-center text-xs leading-5 text-muted-foreground">Based on anomaly frequency, missing observations, temporal consistency and sensor health.</p></Panel><Panel title="Quality Dimensions" eyebrow="Continuous validation"><div className="space-y-5">{metrics.map(([l,v])=><div key={l as string}><div className="mb-2 flex justify-between text-xs"><span>{l}</span><span className="text-data font-semibold">{v}%</span></div><div className="h-2 overflow-hidden rounded-sm bg-muted"><div className={cn("h-full",Number(v)<80?"bg-warning":"bg-primary")} style={{width:`${v}%`}}/></div></div>)}</div></Panel><Panel title="Live Data Stream" eyebrow="Validated AWS observations" className="xl:col-span-2"><StreamTable sim={sim}/></Panel></div>}
function StreamTable({sim}:{sim:SimState}){const rows=Array.from({length:7},(_,i)=>({time:`10:${43-i}:${String(20-i*2).padStart(2,"0")}`,t:sim.active&&i===0?55:(24.8-i*.1).toFixed(1),p:sim.active&&i===0?1034:(1008.4+i*.1).toFixed(1),h:sim.active&&i===0?94:(68.2-i*.3).toFixed(1),score:sim.active&&i===0?97:6+i,status:sim.active&&i===0?"ANOMALY":"NORMAL"}));return <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-xs"><thead className="text-[9px] uppercase text-muted-foreground"><tr>{["Timestamp","Temperature","Pressure","Humidity","Anomaly Score","Station Health","Status"].map(h=><th className="border-b border-border px-3 py-2" key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.time} className={i===0&&sim.active?"bg-critical/10":""}><td className="px-3 py-3 text-data">{r.time}</td><td className="px-3">{r.t} °C</td><td className="px-3">{r.p} hPa</td><td className="px-3">{r.h}%</td><td className="px-3">{r.score}/100</td><td className="px-3">{i===0&&sim.active?42:94}%</td><td className={cn("px-3 font-bold",r.status==="ANOMALY"?"text-critical":"text-success")}>{r.status}</td></tr>)}</tbody></table></div>}
function AlertsView({alerts,update,explain}:{alerts:AlertRecord[];update:(id:number,s:string)=>void;explain:()=>void}){const [severity,setSeverity]=useState("All");const filtered=severity==="All"?alerts:alerts.filter(a=>a.severity===severity);return <Panel title="Alert Center" eyebrow={`${filtered.length} operational alerts`} action={<div className="flex items-center gap-2"><Filter className="size-3 text-muted-foreground"/><select value={severity} onChange={e=>setSeverity(e.target.value)} className="rounded-sm border border-input bg-background px-2 py-1 text-[10px]"><option>All</option><option>CRITICAL</option><option>HIGH</option><option>MEDIUM</option></select></div>}><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left text-xs"><thead className="text-[9px] uppercase text-muted-foreground"><tr>{["Priority","Time","Station","Parameter","Anomaly Type","Severity","Confidence","Status","Action"].map(h=><th className="border-b border-border px-3 py-3" key={h}>{h}</th>)}</tr></thead><tbody>{filtered.map(a=><tr key={a.id} className="border-b border-border/60"><td className="px-3 py-4"><b className={a.priority==="P1"?"text-critical":"text-warning"}>{a.priority}</b></td><td className="px-3 text-data">{a.time}</td><td className="px-3 font-semibold">{a.station}</td><td className="px-3">{a.parameter}</td><td className="px-3">{a.type}</td><td className={cn("px-3 font-bold",a.severity==="CRITICAL"?"text-critical":"text-warning")}>{a.severity}</td><td className="px-3 text-data">{a.confidence}%</td><td className="px-3">{a.status}</td><td className="px-3"><div className="flex gap-1"><Button size="sm" variant="command" onClick={()=>update(a.id,"Acknowledged")}>Acknowledge</Button><Button size="sm" variant="ghost" onClick={explain}><Eye/> Explain</Button><Button size="sm" variant="ghost" onClick={()=>update(a.id,"Resolved")}>Resolve</Button></div></td></tr>)}</tbody></table></div></Panel>}
function MaintenanceView({sim}:{sim:SimState}){return <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Maintenance Intelligence" eyebrow="Predictive risk"><div className={cn("rounded-md border p-5",sim.active?"border-critical/40 bg-critical/10":"border-warning/30 bg-warning/5")}><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[9px] font-bold uppercase text-muted-foreground">Maintenance risk</p><h3 className="mt-1 font-display text-3xl font-semibold">{sim.active?"Temperature":"Humidity"} Sensor</h3><p className={cn("mt-2 text-xs font-bold",sim.active?"text-critical":"text-warning")}>Risk level: {sim.active?"CRITICAL":"HIGH"}</p></div><Wrench className={cn("size-9",sim.active?"text-critical":"text-warning")}/></div><p className="mt-5 text-sm text-muted-foreground">Predicted degradation: <b className="text-foreground">Increasing anomaly frequency</b></p><div className="mt-4 rounded-md border border-border bg-background/35 p-3"><p className="text-[9px] font-bold uppercase text-primary">Recommended action</p><p className="mt-1 text-sm">{sim.active?"Inspect temperature sensor and verify calibration immediately.":"Inspect humidity sensor and verify calibration within 7 days."}</p></div></div><div className="mt-5"><HealthChart active={sim.active}/></div></Panel><Panel title="Maintenance Priority Queue" eyebrow="AI prioritized"><div className="space-y-3">{[[sim.active?"P1":"P2","AWS-PN-042",sim.active?"Temperature calibration":"Humidity inspection"],["P2","AWS-SR-005","Humidity drift review"],["P2","AWS-BB-019","Connectivity check"],["P3","AWS-KO-021","Pressure calibration"]].map(([p,id,a],i)=><div key={id} className="flex items-center gap-3 rounded-md border border-border bg-background/30 p-3"><span className={cn("grid size-9 place-items-center rounded-sm font-display font-bold",p==="P1"?"bg-critical/15 text-critical":"bg-warning/15 text-warning")}>{p}</span><div className="min-w-0 flex-1"><p className="text-xs font-semibold">{id}</p><p className="truncate text-[10px] text-muted-foreground">{a}</p></div><span className="text-data text-[10px] text-muted-foreground">{i===0?"NOW":`${i+1}d`}</span></div>)}</div></Panel></div>}
function SimulationView({latest,series,sim,inject,reset,report}:{latest:SensorPoint;series:SensorPoint[];sim:SimState;inject:(t:string,d?:boolean)=>void;reset:()=>void;report:()=>void}){const actions=[["Temperature Spike",Zap],["Frozen Sensor",RefreshCw],["Sensor Drift",TrendingUp],["Missing Data",Database],["Communication Error",Radio],["Multivariate Anomaly",BrainCircuit]] as const;return <div className="space-y-5"><section className="rounded-lg border border-primary/30 bg-primary/[.05] p-5 sm:p-6"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-center"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-primary">Signature judge scenario</p><h2 className="mt-2 font-display text-3xl font-semibold">Demo: Sensor Failure Event</h2><p className="mt-2 max-w-2xl text-xs leading-5 text-muted-foreground">Runs deterministic temperature, humidity and pressure failures through the complete simulated intelligence pipeline.</p></div><div className="flex flex-wrap gap-2"><Button size="lg" onClick={()=>inject("Temperature Spike",true)}><Play/> Run AI Demo</Button><Button size="lg" variant="outline" onClick={reset}><RefreshCw/> Reset Simulation</Button></div></div></section><div className="grid gap-5 xl:grid-cols-[.7fr_1.3fr]"><Panel title="Failure Injection" eyebrow="Operator controls"><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-1">{actions.map(([label,Icon])=><Button key={label} variant="command" className="justify-start" onClick={()=>inject(label)}><Icon/>{`Inject ${label}`}</Button>)}</div><div className="mt-4 border-t border-border pt-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Manual telemetry</p><div className="mt-3 grid grid-cols-3 gap-2"><SmallStat v={`${latest.temperature}°`} l="Temperature"/><SmallStat v={`${latest.pressure}`} l="Pressure"/><SmallStat v={`${latest.humidity}%`} l="Humidity"/></div></div></Panel><Panel title="Live Simulation Telemetry" eyebrow={`Sequence step ${sim.step}/5`}><TelemetryChart data={series} anomaly={sim.active}/></Panel></div><div className="grid gap-5 xl:grid-cols-3"><Panel title="AI Detection" eyebrow="Decision"><div className="flex items-center gap-4"><GaugeRing value={sim.score} label="Anomaly" tone={sim.score>80?"critical":"primary"} size="sm"/><div><p className={cn("text-sm font-bold",sim.active?"text-critical":"text-success")}>{sim.active?"CRITICAL ANOMALY DETECTED":"NORMAL OPERATION"}</p><p className="text-data mt-2 text-2xl">{sim.confidence}% <span className="text-xs text-muted-foreground">confidence</span></p><p className="mt-1 text-xs text-muted-foreground">{sim.rootCause}</p></div></div></Panel><Consistency sim={sim}/><Panel title="Self-Healing Output" eyebrow="AI-corrected"><div className="grid grid-cols-2 gap-3"><TwinValue label="Observed temperature" v={`${latest.temperature}°C`} bad={sim.active}/><TwinValue label="AI estimated" v={`${sim.active?sim.corrected:latest.temperature}°C`} ai/></div><p className="mt-4 text-xs text-muted-foreground">{sim.active?"Corrected observation is ready for downstream quality-controlled datasets.":"Correction activates only when anomaly confidence crosses the safety threshold."}</p></Panel></div><div className="flex flex-wrap gap-3"><Button variant="command" onClick={report} disabled={!sim.active}><FileText/>Generate Incident Report</Button>{sim.active&&<span className="self-center text-xs text-warning">Maintenance action generated • Sensor health reduced to {sim.health}%</span>}</div></div>}
function ArchitectureView(){const pipeline=["Raw AWS Data","Preprocessing","Feature Engineering","Temporal Analysis","Multivariate Analysis","Anomaly Detection","Root Cause","Explainable AI","Correction","Sensor Health","Predictive Maintenance"];return <div className="space-y-5"><Panel title="AI Intelligence Pipeline" eyebrow="Deployment-ready architecture"><div className="flex flex-wrap items-center justify-center gap-2 py-4">{pipeline.map((p,i)=><div key={p} className="flex items-center gap-2"><div className="rounded-md border border-primary/25 bg-primary/5 px-3 py-3 text-center text-[10px] font-semibold">{p}</div>{i<pipeline.length-1&&<span className="text-primary">→</span>}</div>)}</div></Panel><div className="grid gap-5 lg:grid-cols-2"><Panel title="Hybrid Model Ensemble" eyebrow="Simulated prototype inference"><div className="grid grid-cols-2 gap-3">{["Isolation Forest","Autoencoder","LSTM / Temporal Model","Statistical Residual Analysis","Multivariate Consistency Engine","Root Cause Classifier"].map(m=><div key={m} className="flex items-center gap-2 rounded-md border border-border bg-background/30 p-3 text-xs"><BrainCircuit className="size-4 text-primary"/>{m}</div>)}</div><div className="mt-4 flex items-start gap-2 rounded-md border border-warning/25 bg-warning/5 p-3"><Info className="mt-0.5 size-4 shrink-0 text-warning"/><p className="text-[10px] leading-5 text-muted-foreground">This demonstration uses deterministic simulated inference. The service boundary is designed for replacement by a production Python model API.</p></div></Panel><Panel title="Technology Stack" eyebrow="Cloud-ready"><div className="grid grid-cols-2 gap-x-5 gap-y-3">{[["Frontend","React + TypeScript"],["Visualization","Recharts + map layer"],["Backend target","FastAPI"],["AI / ML","Python • Scikit-learn • PyTorch"],["Explainability","SHAP"],["Database","PostgreSQL"],["Deployment","Cloud-ready"],["Edge target","ESP32-compatible architecture"]].map(([l,v])=><StatusRow key={l} label={l} value={v}/>)}</div><p className="mt-4 text-[10px] text-muted-foreground">Edge deployment is an architectural target and is not implemented in this prototype.</p></Panel></div><Panel title="Closed-Loop Weather Data Intelligence" eyebrow="Core operating model"><div className="grid gap-3 md:grid-cols-4">{[["DETECT","Find anomalies before they become operational risks.",Search],["EXPLAIN","Understand why the AI flagged the observation.",Eye],["CORRECT","Estimate trustworthy values when sensor readings fail.",RefreshCw],["PREDICT","Identify degrading sensors before complete failure.",TrendingUp]].map(([h,p,I],i)=><div key={h as string} className="relative rounded-md border border-border bg-background/30 p-4"><I className="text-primary"/><h3 className="mt-3 font-display text-xl font-semibold text-primary">{h as string}</h3><p className="mt-1 text-[10px] leading-5 text-muted-foreground">{p as string}</p>{i<3&&<span className="absolute -right-2.5 top-1/2 z-10 hidden text-primary md:block">→</span>}</div>)}</div></Panel></div>}
function IncidentReport({sim,station,latest,close}:{sim:SimState;station:Station;latest:SensorPoint;close:()=>void}){const download=()=>{const text=`SKYGUARD AI — INCIDENT REPORT\nStation: ${station.id}, ${station.city}\nTimestamp: 10:43:20 IST\nDetected anomaly: ${sim.type}\nAffected parameter: Temperature\nObserved value: ${latest.temperature} °C\nExpected value: 28.7 °C\nAnomaly score: ${sim.score}/100\nConfidence: ${sim.confidence}%\nRoot cause: ${sim.rootCause}\nAI explanation: Observation conflicts with temporal history, humidity behavior, pressure trend, and neighboring stations.\nCorrected value: ${sim.corrected} °C\nSensor health: ${sim.health}%\nRecommended action: Inspect temperature sensor and verify calibration.`;const blob=new Blob([text],{type:"text/plain"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`skyguard-incident-${station.id}.txt`;a.click();URL.revokeObjectURL(url);toast.success("Incident report downloaded")};return <div className="fixed inset-0 z-50 grid place-items-center bg-background/85 p-4 backdrop-blur-md"><div role="dialog" aria-modal="true" aria-labelledby="report-title" className="glass-panel max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-lg"><header className="no-print flex items-center justify-between border-b border-border p-4"><div><p className="text-[9px] font-bold uppercase text-primary">Generated incident artifact</p><h2 id="report-title" className="font-display text-2xl font-semibold">Incident Report</h2></div><Button variant="ghost" size="icon" onClick={close} aria-label="Close report"><X/></Button></header><div className="p-6 sm:p-8"><Brand/><div className="mt-7 flex flex-wrap items-center justify-between gap-3 border-y border-border py-4"><div><p className="text-[9px] uppercase text-muted-foreground">Incident</p><p className="text-lg font-semibold">{sim.type}</p></div><span className="rounded-sm border border-critical/40 bg-critical/10 px-3 py-2 text-xs font-bold text-critical">CRITICAL • P1</span></div><div className="mt-6 grid gap-x-8 gap-y-4 sm:grid-cols-2">{[["Station",`${station.id} — ${station.city}`],["Timestamp","10:43:20 IST"],["Affected parameter","Temperature"],["Observed value",`${latest.temperature} °C`],["Expected value","28.7 °C"],["AI corrected value",`${sim.corrected} °C`],["Anomaly score",`${sim.score}/100`],["Confidence",`${sim.confidence}%`],["Root cause",sim.rootCause],["Sensor health",`${sim.health}%`]].map(([l,v])=><div key={l} className="border-b border-border pb-3"><p className="text-[9px] font-bold uppercase text-muted-foreground">{l}</p><p className="mt-1 text-sm">{v}</p></div>)}</div><div className="mt-6 rounded-md border border-primary/25 bg-primary/5 p-4"><p className="text-[9px] font-bold uppercase text-primary">AI explanation</p><p className="mt-2 text-sm leading-6 text-muted-foreground">Observation conflicts with recent station history, expected humidity behavior, pressure trend, and neighboring station observations.</p></div><div className="mt-4 rounded-md border border-warning/25 bg-warning/5 p-4"><p className="text-[9px] font-bold uppercase text-warning">Recommended action</p><p className="mt-2 text-sm">Inspect temperature sensor and verify calibration.</p></div><div className="no-print mt-6 flex flex-wrap justify-end gap-2"><Button variant="command" onClick={()=>window.print()}><Printer/>Print Report</Button><Button onClick={download}><Download/>Download Report</Button></div></div></div></div>}
